import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import zeros = require( '@stdlib/ndarray/zeros' );
import array = require( '@stdlib/ndarray/array' );
import stdev = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );

	stdev( x, correction ); // $ExpectType OutputArray<unknown>
	stdev( x, correction, {} ); // $ExpectType OutputArray<unknown>
	stdev( x, correction, { 'dims': [ 0 ] } ); // $ExpectType OutputArray<unknown>
	stdev( x, correction, { 'keepdims': true } ); // $ExpectType OutputArray<unknown>
	stdev( x, correction, { 'dtype': 'float64' } ); // $ExpectType OutputArray<unknown>
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	const correction = scalar2ndarray( 1.0 );

	stdev( '5', correction ); // $ExpectError
	stdev( 5, correction ); // $ExpectError
	stdev( true, correction ); // $ExpectError
	stdev( false, correction ); // $ExpectError
	stdev( null, correction ); // $ExpectError
	stdev( void 0, correction ); // $ExpectError
	stdev( {}, correction ); // $ExpectError
	stdev( [ 1 ], correction ); // $ExpectError
	stdev( ( x: number ): number => x, correction ); // $ExpectError

	stdev( '5', correction, {} ); // $ExpectError
	stdev( 5, correction, {} ); // $ExpectError
	stdev( true, correction, {} ); // $ExpectError
	stdev( false, correction, {} ); // $ExpectError
	stdev( null, correction, {} ); // $ExpectError
	stdev( void 0, correction, {} ); // $ExpectError
	stdev( {}, correction, {} ); // $ExpectError
	stdev( [ 1 ], correction, {} ); // $ExpectError
	stdev( ( x: number ): number => x, correction, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );

	stdev( x, '5' ); // $ExpectError
	stdev( x, 5 ); // $ExpectError
	stdev( x, true ); // $ExpectError
	stdev( x, false ); // $ExpectError
	stdev( x, null ); // $ExpectError
	stdev( x, void 0 ); // $ExpectError
	stdev( x, {} ); // $ExpectError
	stdev( x, [ 1 ] ); // $ExpectError
	stdev( x, ( x: number ): number => x ); // $ExpectError

	stdev( x, '5', {} ); // $ExpectError
	stdev( x, 5, {} ); // $ExpectError
	stdev( x, true, {} ); // $ExpectError
	stdev( x, false, {} ); // $ExpectError
	stdev( x, null, {} ); // $ExpectError
	stdev( x, void 0, {} ); // $ExpectError
	stdev( x, {}, {} ); // $ExpectError
	stdev( x, [ 1 ], {} ); // $ExpectError
	stdev( x, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );

	stdev( x, correction, '5' ); // $ExpectError
	stdev( x, correction, 5 ); // $ExpectError
	stdev( x, correction, true ); // $ExpectError
	stdev( x, correction, false ); // $ExpectError
	stdev( x, correction, null ); // $ExpectError
	stdev( x, correction, [ 1 ] ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );

	stdev(); // $ExpectError
	stdev( x ); // $ExpectError
	stdev( x, correction, {}, {} ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns an ndarray...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );
	const out = zeros( [] );

	stdev.assign( x, correction, out ); // $ExpectType float64ndarray
	stdev.assign( x, correction, out, {} ); // $ExpectType float64ndarray
	stdev.assign( x, correction, out, { 'dims': [ 0 ] } ); // $ExpectType float64ndarray
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an ndarray...
{
	const correction = scalar2ndarray( 1.0 );
	const out = zeros( [] );

	stdev.assign( '5', correction, out ); // $ExpectError
	stdev.assign( 5, correction, out ); // $ExpectError
	stdev.assign( true, correction, out ); // $ExpectError
	stdev.assign( false, correction, out ); // $ExpectError
	stdev.assign( null, correction, out ); // $ExpectError
	stdev.assign( void 0, correction, out ); // $ExpectError
	stdev.assign( {}, correction, out ); // $ExpectError
	stdev.assign( [ 1 ], correction, out ); // $ExpectError
	stdev.assign( ( x: number ): number => x, correction, out ); // $ExpectError

	stdev.assign( '5', correction, out, {} ); // $ExpectError
	stdev.assign( 5, correction, out, {} ); // $ExpectError
	stdev.assign( true, correction, out, {} ); // $ExpectError
	stdev.assign( false, correction, out, {} ); // $ExpectError
	stdev.assign( null, correction, out, {} ); // $ExpectError
	stdev.assign( void 0, correction, out, {} ); // $ExpectError
	stdev.assign( {}, correction, out, {} ); // $ExpectError
	stdev.assign( [ 1 ], correction, out, {} ); // $ExpectError
	stdev.assign( ( x: number ): number => x, correction, out, {} ); // $ExpectError
}

