// The compiler throws an error if the `assign` method is provided an options argument which is not an object...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );
	const out = zeros( [] );

	stdev.assign( x, correction, out, '5' ); // $ExpectError
	stdev.assign( x, correction, out, 5 ); // $ExpectError
	stdev.assign( x, correction, out, true ); // $ExpectError
	stdev.assign( x, correction, out, false ); // $ExpectError
	stdev.assign( x, correction, out, null ); // $ExpectError
	stdev.assign( x, correction, out, [ 1 ] ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an unsupported number of arguments...
{
	const x = array( [ 1.0, -2.0, 2.0 ] );
	const correction = scalar2ndarray( 1.0 );
	const out = zeros( [] );

	stdev.assign(); // $ExpectError
	stdev.assign( x ); // $ExpectError
	stdev.assign( x, correction ); // $ExpectError
	stdev.assign( x, correction, out, {}, {} ); // $ExpectError
}
